# Generated by build.py from recipe.yml for recipe dns-resolve-names-over-tls. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/dns', 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/dns/example.test.zone'), "`$ORIGIN example.test.`n`$TTL 300`n@   IN SOA ns1.example.test. hostmaster.example.test. 1 3600 600 86400 300`n@   IN NS  ns1.example.test.`napi IN A   127.0.0.1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/status.txt'), "orders api: up`n")
[IO.File]::WriteAllText((Join-Path $PWD 'call-by-name.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh call-by-name.sh DNS-PORT NAME HTTP-PORT PATH. Looks NAME up over DNS over TLS on`n# 127.0.0.1:DNS-PORT, trusting server.pem, then fetches http://NAME:HTTP-PORT/PATH from the`n# address the answer gave. A failed lookup exits with curl's code; no A record exits 6.`nanswer=`$(curl -sS --max-time 10 --dns-transport tls --cacert server.pem `"dns://127.0.0.1:`$1/`$2`") || exit`naddr=`$(printf '%s\n' `"`$answer`" | awk -F '\t' 'NF == 5 && `$4 == `"A`" { print `$5; exit }')`nif [ -z `"`$addr`" ]; then echo `"`$2 did not resolve`" >&2; exit 6; fi`necho `"`$2 is `$addr`"`ncurl -sS --max-time 10 --resolve `"`$2:`$3:`$addr`" `"http://`$2:`$3`$4`"`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--dns-transport', 'tls', 'dns://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh call-by-name.sh 8080 api.example.test 8081 /status.txt } finally { Stop-Process $server0 }
